    "memo": "방과후가 행복한 안심 돌봄 공간, 수인분당선 월곶역에 있는 솔로몬지역아동센터에서 열정 있는 실습생을 모집합니다. 실습생 개별 맞춤 실습지원으로, 그동안 실습생 전원 100%가 실습 과정을 무사히 수료하였습니다. 실습생 모두가 만족할 수 있도록 실습 전 과정과 일정을 전문 사회복지사 수퍼바이저가 꼼꼼하게 친절히 지원해 드립니다. 전문 지식이나 관련 경력이 없어도, 난생 처음 해보는 아동지도라도 정해진 매뉴얼에 따라 성실하게 참여하시면 누구나 실습",
